package dominoes

// Domino represents a domino tile with two values.
type Domino [2]int

// MakeChain takes a set of dominoes and returns a valid chain
// (a cycle where adjacent ends match and the chain's ends match),
// and a bool indicating whether a valid chain was found.
func MakeChain(input []Domino) ([]Domino, bool) {
    if len(input) == 0 {
        return []Domino{}, true
    }
    // Backtracking search.
    var chain []Domino
    remaining := make([]Domino, len(input))
    copy(remaining, input)
    if find(remaining, nil) {
        return chain, true
    }
    return nil, false
}
```

