```go
func MakeChain(input []Domino) ([]Domino, bool) {
    n := len(input)
    if n == 0 {
        return []Domino{}, true
    }

    // Degree check.
    deg := map[int]int{}
    for _, d := range input {
        deg[d[0]]++
        deg[d[1]]++
    }
    for _, v := range deg {
        if v%2 != 0 {
            return nil, false
        }
    }

    // Connectivity check over vertices with nonzero degree.
    // (Only relevant if n > 0; if all degrees are even and n>0, at least one vertex exists.)
    adj := map[int][]int{}
    for _, d := range input {
        adj[d[0]] = append(adj[d[0]], d[1])
        adj[d[1]] = append(adj[d[1]], d[0])
    }
    start := 0
    for v := range deg {
        start = v
        break
    }
    visited := map[int]bool{}
    stack := []int{start}
    for len(stack) > 0 {
        v := stack[len(stack)-1]
        stack = stack[:len(stack)-1]
        if visited[v] {
            continue
        }
        visited[v] = true
        for _, w := range adj[v] {
            if !visited[w] {
                stack = append(stack, w)
            }
        }
    }
    for v := range deg {
        if !visited[v] {
            return nil, false
        }
    }

    // Hierholzer.
    // Edge list per vertex with an index pointer.
    edges := map[int][]int{}
    for _, d := range input {
        edges[d[0]] = append(edges[d[0]], d[1])
        edges[d[1]] = append(edges[d[1]], d[0])
    }
    pos := map[int]int{}
    var circuit []int
    stack := []int{start}
    for len(stack) > 0 {
        v := stack[len(stack)-1]
        p := pos[v]
        if p < len(edges[v]) {
            pos[v] = p + 1
            stack = append(stack, edges[v][p])
        } else {
            circuit = append(circuit, v)
            stack = stack[:len(stack)-1]
        }
    }
    if len(circuit) != n+1 {
        return nil, false // Shouldn't happen given the pre-check.
    }
    chain := make([]Domino, n)
    for i := 0; i < n; i++ {
        chain[i] = Domino{circuit[i], circuit[i+1]}
    }
    return chain, true
}
```

